>prepare('UPDATE student_financial_items SET paid_amount=270,status="PAID" WHERE id=?')->execute([$id]);$paid=$service->update($id,['discount_type'=>'FIXED','discount_value'=>0,'notes'=>'Interdit']);ok(isset($paid['error'])&&str_contains($paid['error'],'payée'),'Paid charge modification was allowed');$q=$p->prepare('SELECT COUNT(*) FROM student_financial_item_history WHERE student_financial_item_id=?');$q->execute([$id]);ok((int)$q->fetchColumn()>=2,'Charge history missing');echo "financial charge mutability integration: OK\n";
